/* eslint-disable @next/next/no-img-element -- heatmap is a data: URL generated by the API */
import type { ForensicsResult } from "@/lib/types";

export function ForensicsTab({ forensics: f }: { forensics: ForensicsResult }) {
  return (
    <div className="space-y-8">
      <div className="space-y-2">
        <h3 className="text-base font-semibold">Visual forensic measurements</h3>
        <p className="max-w-prose text-sm text-muted-foreground">
          Plain signal measurements taken from the pixels{f.region ? ` (${f.region})` : ""}. They describe the image; they do not classify it. No
          decision threshold has been validated for them, so none of them influenced the assessment.
        </p>
      </div>

      {f.signals.length > 0 && (
        <dl className="divide-y divide-border rounded-lg border border-border bg-card">
          {f.signals.map((s) => (
            <div key={s.id} className="grid gap-1 p-4 sm:grid-cols-[minmax(0,14rem)_1fr] sm:gap-6">
              <dt>
                <span className="font-medium">{s.label}</span>
                <span className="num mt-0.5 block text-xl font-semibold">
                  {s.value ?? "n/a"} <span className="text-xs font-normal text-muted-foreground">{s.unit}</span>
                </span>
              </dt>
              <dd className="text-sm text-muted-foreground">{s.interpretation}</dd>
            </div>
          ))}
        </dl>
      )}

      {f.ela && (
        <section aria-labelledby="ela-heading" className="space-y-3">
          <h4 id="ela-heading" className="text-sm font-semibold">Error-level analysis</h4>
          {f.ela.applicable && f.ela.heatmap_data_url ? (
            <div className="grid gap-4 md:grid-cols-[minmax(0,22rem)_1fr]">
              <img
                src={f.ela.heatmap_data_url}
                alt="Error-level analysis heatmap. Brighter areas changed more when the image was re-saved at JPEG quality 90."
                className="w-full rounded-lg border border-border"
              />
              <div className="space-y-2 text-sm text-muted-foreground">
                <p className="num">Mean difference {f.ela.mean}, 99th percentile {f.ela.p99} (8-bit levels).</p>
                <p>{f.ela.note}</p>
              </div>
            </div>
          ) : (
            <p className="text-sm text-muted-foreground">{f.ela.reason}</p>
          )}
        </section>
      )}

      {f.notes.map((n) => (
        <p key={n} className="max-w-prose text-sm text-muted-foreground">{n}</p>
      ))}
    </div>
  );
}
